/// How many there are.
pub const DEEPER_COUNT: usize = 4166;

/// Implements part of the longer-routine family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Routine> {
    DEEPER
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &DEEPER[at])
}

/// Implements part of the longer-routine family.
///
/// How deep one routine goes. Zero means nothing sits inside anything.
#[must_use]
pub fn deepest(held: &Routine) -> u8 {
    held.steps.iter().map(|step| step.depth).max().unwrap_or(0)
}

/// Implements part of the longer-routine family.
///
/// What share of these routines have something inside something else.
#[must_use]
pub fn share_nesting() -> f64 {
    let nested = DEEPER.iter().filter(|held| deepest(held) > 0).count();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        nested as f64 / DEEPER.len() as f64
    }
}

/// Implements part of the longer-routine family.
///
/// How many calls the average step at one depth makes.
#[must_use]
pub fn calls_at_depth(depth: u8) -> f64 {
    let steps: Vec<&Step> = DEEPER
        .iter()
        .flat_map(|held| held.steps.iter())
        .filter(|step| step.depth == depth)
        .collect();
    if steps.is_empty() {
        return 0.0;
    }
    let calls: usize = steps.iter().map(|step| step.calls.len()).sum();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        calls as f64 / steps.len() as f64
    }
}

/// Implements part of the longer-routine family.
///
/// Whether a routine is a constructor.
#[must_use]
pub fn is_a_constructor(held: &Routine) -> bool {
    held.steps
        .iter()
        .any(|step| step.calls.contains(&MAKES_AN_INSTANCE))
        && held
            .steps
            .iter()
            .any(|step| step.calls.contains(&AFTER_IT_IS_MADE))
}

/// Implements part of the longer-routine family.
///
/// Every routine that is a constructor.
#[must_use]
pub fn constructors() -> Vec<&'static Routine> {
    DEEPER
        .iter()
        .filter(|held| is_a_constructor(held))
        .collect()
}

/// Implements part of the longer-routine family.
///
/// Whether the two halves of a constructor sit in different steps.
#[must_use]
pub fn halves_are_apart(held: &Routine) -> bool {
    let makes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&MAKES_AN_INSTANCE));
    let finishes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&AFTER_IT_IS_MADE));
    match (makes, finishes) {
        (Some(one), Some(other)) => one != other,
        _ => false,
    }
}

/// Implements part of the longer-routine family.
///
/// Every routine that tries a value against one constant after another.
#[must_use]
pub fn chains_of_cases() -> Vec<&'static Routine> {
    DEEPER
        .iter()
        .filter(|held| {
            held.steps
                .iter()
                .filter(|step| matches!(step.does, Does::AskingOtherwise(_)))
                .count()
                >= 2
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(DEEPER.len(), DEEPER_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            DEEPER
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = DEEPER[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn none_of_these_is_in_the_shorter_table() {
        for held in DEEPER.iter().take(400) {
            assert!(
                crate::nested_routines::routine_at(held.routine).is_none(),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn every_recorded_call_is_a_function_that_was_recovered() {
        for held in &DEEPER {
            for call in held.steps.iter().flat_map(|step| step.calls.iter()) {
                assert!(
                    (FIRST_RECOVERED..=LAST_RECOVERED).contains(call),
                    "{call:#010X} in {:#010X}",
                    held.routine
                );
            }
        }
    }

    #[test]
    fn the_depths_of_a_routine_only_ever_step_down_by_one() {
        for held in &DEEPER {
            let mut last = 0_u8;
            for step in held.steps {
                assert!(step.depth <= last + 1, "{:#010X}", held.routine);
                last = step.depth;
            }
        }
    }

    #[test]
    fn these_go_deeper_than_the_shorter_routines_do() {
        let here = DEEPER.iter().map(deepest).max().expect("some");
        let there = crate::nested_routines::NESTED
            .iter()
            .map(crate::nested_routines::deepest)
            .max()
            .expect("some");

        assert!(here > there, "{here} against {there}");
    }

    #[test]
    fn and_they_nest_more_often() {
        // Not a fact about the decompiler: it is what the extra length is
        // spent on.
        let here = share_nesting();
        let there = crate::nested_routines::share_nesting();

        assert!(here > there, "{here} against {there}");
        assert!(here > 0.5, "{here}");
    }

    #[test]
    fn the_work_still_sits_at_the_top_and_thins_below_it() {
        // The same fall as in the shorter routines, from a higher start.
        assert!(calls_at_depth(0) > calls_at_depth(1));
        assert!(calls_at_depth(1) > calls_at_depth(2));
        assert!(calls_at_depth(2) > calls_at_depth(3));
        assert!(calls_at_depth(0) > 1.5, "{}", calls_at_depth(0));
    }

    #[test]
    fn a_depth_nothing_reaches_averages_nothing() {
        assert!((calls_at_depth(200) - 0.0).abs() < f64::EPSILON);
    }

    #[test]
    fn many_of_them_are_constructors() {
        assert!(constructors().len() > 100);
    }

    #[test]
    fn and_in_every_one_the_two_halves_sit_in_different_steps() {
        // The third separate population in which this has held without a single
        // exception, each swept a different way.
        for held in constructors() {
            assert!(halves_are_apart(held), "{:#010X}", held.routine);
        }
    }

    #[test]
    fn some_of_them_try_a_value_against_one_constant_after_another() {
        assert!(!chains_of_cases().is_empty());
    }

    #[test]
    fn some_of_them_call_through_a_thunk() {
        let thunked = DEEPER.iter().filter(|held| held.through_a_thunk).count();

        assert!(thunked > 0);
        assert!(thunked < DEEPER.len() / 2);
    }

    #[test]
    fn every_routine_calls_something_and_asks_something() {
        for held in &DEEPER {
            assert!(
                held.steps.iter().any(|step| !step.calls.is_empty()),
                "{:#010X}",
                held.routine
            );
            assert!(
                held.steps
                    .iter()
                    .any(|step| step.does != Does::Straightaway),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = DEEPER.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
